// #2897 AC1: "Each server's `initialize` result holds `instructions` equal to the generated text, at most 1,000
// characters, and `deep`'s names `deep_status` as the call a task begins with. On the merge base no server sends any, and
// this test fails, naming the server"
//
// Each of the four servers (README: The four servers) is started fresh and initialized as Claude Code. Its instructions
// must be one of the strings scripts/skill.mjs's generate() returns ("the text is generated by scripts/skill.mjs from the
// Building blocks table, as the skill and tools.json are"), at most 1,000 characters; deep's must name deep_status as the
// call a task begins with. Every failure line starts with the server's name and how it was started.
import { expect, test } from 'vitest';
import { AC, DEEP, SERVERS, generatedStrings, instructionFailures, startSession } from './helpers.ts';

test(`${AC.instructions} each of the four servers answers initialize with instructions scripts/skill.mjs generates, at most 1,000 characters, and deep's name deep_status as the call a task begins with; a server with none is named`, { timeout: 120_000 }, async () => {
  const generated = await generatedStrings();
  const failures: string[] = [];
  for (const server of SERVERS) {
    const session = await startSession(server);
    failures.push(...instructionFailures(server.label, session, generated, server === DEEP));
  }
  expect(failures, 'each server\'s instructions, as the issue states them').toEqual([]);
});
